class TemplateEditor extends StatefulWidget{
  final LocalStore store;final Json? initial;const TemplateEditor({super.key,required this.store,this.initial});@override State<TemplateEditor> createState()=>_TemplateEditorState();
}
class _TemplateEditorState extends State<TemplateEditor>{final form=GlobalKey<FormState>();late Json data={...?widget.initial,'itemsText':strings(widget.initial?['items']).join('\n')};bool busy=false;
  Future<void> save()async{if(busy||!(form.currentState?.validate()??false))return;final items=str(data['itemsText']).split('\n').map((s)=>s.trim()).where((s)=>s.isNotEmpty).toList();if(items.isEmpty){toast(context,'Mindestens einen Prüfpunkt eingeben.');return;}setState(()=>busy=true);await guarded(context,()async{await widget.store.save('hygieneTemplate',{...data,'items':items}..remove('itemsText'));if(mounted)Navigator.pop(context,true);});if(mounted)setState(()=>busy=false);}
  @override Widget build(BuildContext context)=>PageFrame(title:'Hygienevorlage',child:Form(key:form,child:ListView(padding:const EdgeInsets.all(12),children:[Fields(specs:const [FieldSpec('name','Name',required:true),FieldSpec('itemsText','Prüfpunkte (einer je Zeile)',multiline:true,required:true),FieldSpec('notes','Hintergrund / Anweisungen',multiline:true)],data:data,changed:()=>setState((){})),FilledButton(onPressed:busy?null:save,child:const Text('Speichern'))])));
}
class HygieneEditor extends StatefulWidget{
  final LocalStore store;final Json? template;const HygieneEditor({super.key,required this.store,this.template});@override State<HygieneEditor> createState()=>_HygieneEditorState();
}
class _HygieneEditorState extends State<HygieneEditor>{final form=GlobalKey<FormState>();late Json? template=widget.template;late Json data={'name':template==null?'Hygienekontrolle':nameOf(template!),'date':today(),'time':'${DateTime.now().hour.toString().padLeft(2,'0')}:${DateTime.now().minute.toString().padLeft(2,'0')}'};late List<Json> items=strings(template?['items']).map((s)=><String,dynamic>{'name':s,'status':'Offen','notes':''}).toList();List<Json> measurements=[];int revision=0;bool busy=false;
  void changed()=>setState((){});
  Future<void> selectTemplate()async{final result=await showDialog<Json>(context:context,builder:(ctx)=>SimpleDialog(title:const Text('Vorlage auswählen'),children:[for(final t in widget.store.all('hygieneTemplate'))SimpleDialogOption(onPressed:()=>Navigator.pop(ctx,t),child:Text(nameOf(t)))]));if(result==null||!mounted)return;if(items.isNotEmpty&&!await confirm(context,'Checkliste ersetzen?','Bestehende Prüfpunkte werden ersetzt.'))return;if(!mounted)return;setState((){template=result;items=strings(result['items']).map((s)=><String,dynamic>{'name':s,'status':'Offen','notes':''}).toList();data['name']=nameOf(result);revision++;});}
  Future<void> addMeasurement()async{final value=await showDialog<Json>(context:context,builder:(_)=>const _MeasurementDialog());if(value!=null&&mounted)setState(()=>measurements.add(value));}
  Future<void> save()async{if(busy||!(form.currentState?.validate()??false))return;if(items.isEmpty&&measurements.isEmpty){toast(context,'Mindestens einen Prüfpunkt oder Messwert erfassen.');return;}if(items.any((i)=>i['status']=='Abweichung'&&str(i['notes']).trim().isEmpty)){toast(context,'Bei jeder Abweichung eine Maßnahme / Notiz ergänzen.');return;}if(items.any((i)=>i['status']=='Offen')&&!await confirm(context,'Offene Prüfpunkte','Die Kontrolle wird unvollständig gespeichert, nicht als bestanden.'))return;if(!mounted)return;setState(()=>busy=true);await guarded(context,()async{await widget.store.save('hygieneCheck',{...data,'templateSnapshot':template,'items':items,'measurements':measurements,'status':items.any((i)=>i['status']=='Abweichung')?'Abweichung':items.any((i)=>i['status']=='Offen')?'Unvollständig':'Dokumentiert'});if(mounted)Navigator.pop(context,true);});if(mounted)setState(()=>busy=false);}
  @override Widget build(BuildContext context){final productions=widget.store.all('production');return PageFrame(title:'Hygienekontrolle erfassen',child:Form(key:form,child:ListView(padding:const EdgeInsets.all(12),children:[Section('Grunddaten',[OutlinedButton.icon(onPressed:selectTemplate,icon:const Icon(Icons.list),label:Text(template==null?'Checkliste auswählen':nameOf(template!))),Fields(key:ValueKey('h-$revision'),specs:const [FieldSpec('name','Bezeichnung',required:true),FieldSpec('date','Datum (JJJJ-MM-TT)',date:true,required:true),FieldSpec('time','Uhrzeit',required:true),FieldSpec('responsible','Verantwortliche Person',required:true)],data:data,changed:changed),DropdownButtonFormField<String>(isExpanded:true,value:productions.any((p)=>p['id']==data['productionId'])?str(data['productionId']):'',items:[const DropdownMenuItem(value:'',child:Text('Keine Zuordnung')),for(final p in productions)DropdownMenuItem(value:str(p['id']),child:Text('${nameOf(p)} · ${str(p['productionNumber'])}',overflow:TextOverflow.ellipsis))],decoration:const InputDecoration(labelText:'Produktion (optional)'),onChanged:(v)=>setState(()=>data['productionId']=v))]),Section('Prüfpunkte',[for(var i=0;i<items.length;i++)Padding(key:ValueKey('$revision-$i'),padding:const EdgeInsets.only(bottom:10),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(nameOf(items[i]),style:Theme.of(context).textTheme.titleSmall),Fields(specs:const [FieldSpec('status','Ergebnis',choices:['Offen','Erledigt','Abweichung','Nicht anwendbar'],required:true),FieldSpec('notes','Bemerkung / Korrekturmaßnahme',multiline:true)],data:items[i],changed:changed),const Divider()])),if(items.isEmpty)const Text('Noch keine Prüfpunkte.'),OutlinedButton.icon(onPressed:()async{final result=await showDialog<String>(context:context,builder:(_)=>const _PointDialog());if(result!=null&&mounted)setState(()=>items.add({'name':result,'status':'Offen','notes':''}));},icon:const Icon(Icons.add),label:const Text('Eigenen Prüfpunkt hinzufügen'))]),Section('Soll-/Ist-Werte und Kontrollpunkte',[for(var i=0;i<measurements.length;i++)ListTile(contentPadding:EdgeInsets.zero,title:Text(nameOf(measurements[i])),subtitle:Text('Soll: ${str(measurements[i]['target'])} · Ist: ${str(measurements[i]['actual'])} ${str(measurements[i]['unit'])}\n${str(measurements[i]['notes'])}'),trailing:IconButton(onPressed:()=>setState(()=>measurements.removeAt(i)),icon:const Icon(Icons.delete_outline))),OutlinedButton.icon(onPressed:addMeasurement,icon:const Icon(Icons.add),label:const Text('Messung / Kontrollpunkt erfassen'))]),Section('Abweichungen und Maßnahmen',[Fields(specs:const [FieldSpec('notes','Reinigung, Kühlkette, Korrekturmaßnahmen und weitere Hinweise',multiline:true)],data:data,changed:changed)]),FilledButton.icon(onPressed:busy?null:save,icon:const Icon(Icons.save),label:const Text('Hygieneprotokoll speichern')),const SizedBox(height:24)])));}
}
class _PointDialog extends StatefulWidget{const _PointDialog();@override State<_PointDialog> createState()=>_PointDialogState();}
class _PointDialogState extends State<_PointDialog>{String value='';@override Widget build(BuildContext context)=>AlertDialog(title:const Text('Eigener Prüfpunkt'),content:TextField(autofocus:true,onChanged:(v)=>setState(()=>value=v),decoration:const InputDecoration(labelText:'Bezeichnung')),actions:[TextButton(onPressed:()=>Navigator.pop(context),child:const Text('Abbrechen')),FilledButton(onPressed:value.trim().isEmpty?null:()=>Navigator.pop(context,value.trim()),child:const Text('Hinzufügen'))]);}
class _MeasurementDialog extends StatefulWidget{const _MeasurementDialog();@override State<_MeasurementDialog> createState()=>_MeasurementDialogState();}
class _MeasurementDialogState extends State<_MeasurementDialog>{final form=GlobalKey<FormState>();final data=<String,dynamic>{};@override Widget build(BuildContext context)=>AlertDialog(title:const Text('Kontrollpunkt / Messung'),content:Form(key:form,child:SingleChildScrollView(child:Fields(specs:const [FieldSpec('name','Kontrollpunkt',required:true),FieldSpec('target','Betrieblicher Sollwert / Bereich'),FieldSpec('actual','Istwert',required:true),FieldSpec('unit','Einheit (z. B. °C, min)'),FieldSpec('time','Uhrzeit / Dauer'),FieldSpec('notes','Bewertung / Abweichung / Maßnahme',multiline:true,required:true)],data:data,changed:()=>setState((){})))),actions:[TextButton(onPressed:()=>Navigator.pop(context),child:const Text('Abbrechen')),FilledButton(onPressed:(){if(form.currentState?.validate()??false)Navigator.pop(context,data);},child:const Text('Übernehmen'))]);}
class HygieneHistory extends StatelessWidget{final LocalStore store;const HygieneHistory({super.key,required this.store});
  @override Widget build(BuildContext context)=>AnimatedBuilder(animation:store,builder:(context,_) {final entries=store.all('hygieneCheck')..sort((a,b)=>str(b['created']).compareTo(str(a['created'])));return PageFrame(title:'Hygienehistorie',child:entries.isEmpty?const EmptyState('Noch keine Hygieneprotokolle.'):ListView.builder(itemCount:entries.length,itemBuilder:(_,i){final r=entries[i];return Card(child:ListTile(title:Text(nameOf(r)),subtitle:Text('${str(r['date'])} · ${str(r['status'])}'),onTap:()=>openPage(context,HygieneDetail(record:r))));}));});
}
class HygieneDetail extends StatelessWidget{final Json record;const HygieneDetail({super.key,required this.record});
  @override Widget build(BuildContext context){final items=maps(record['items']),measurements=maps(record['measurements']);return PageFrame(title:nameOf(record),actions:[IconButton(icon:const Icon(Icons.picture_as_pdf_outlined),onPressed:()=>guarded(context,()async{await LocalFiles.report(nameOf(record),[('Datum / Uhrzeit','${str(record['date'])} ${str(record['time'])}'),('Verantwortlich',str(record['responsible'])),('Status',str(record['status'])),for(final i in items)(nameOf(i),'${str(i['status'])}: ${str(i['notes'])}'),for(final m in measurements)(nameOf(m),'Soll ${str(m['target'])} / Ist ${str(m['actual'])} ${str(m['unit'])} · ${str(m['time'])} · ${str(m['notes'])}'),('Notizen',str(record['notes']))]);}))],child:ListView(padding:const EdgeInsets.all(12),children:[ValueRow('Datum','${str(record['date'])} ${str(record['time'])}'),ValueRow('Verantwortlich',str(record['responsible'])),ValueRow('Status',str(record['status'])),Section('Prüfpunkte',[for(final i in items)ListTile(contentPadding:EdgeInsets.zero,title:Text(nameOf(i)),subtitle:Text('${str(i['status'])}\n${str(i['notes'])}'))]),Section('Messungen',[for(final m in measurements)ListTile(contentPadding:EdgeInsets.zero,title:Text(nameOf(m)),subtitle:Text('Soll ${str(m['target'])} / Ist ${str(m['actual'])} ${str(m['unit'])}\n${str(m['time'])} ${str(m['notes'])}'))]),ValueRow('Notizen',str(record['notes']))]));}
}
